import java.io.*;
import java.util.*;

public class TaskD {
    private static final long[] H1 = {0, 0, 0, 0, 2, 4};
    private static final long[] H2 = {0, 0, 0, 4, 8, 10};
    private static final long[] H3 = {0, 0, 4, 8, 12, 14};

    boolean eof;
    BufferedReader br;
    StringTokenizer st;
    PrintWriter out;

    public static void main(String[] args) throws IOException {
        new TaskD().run();
    }

    String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return "-1";
            }
        }
        return st.nextToken();
    }

    long nextLong() {
        return Long.parseLong(nextToken());
    }

    void run() throws IOException {
        InputStream input = System.in;
        PrintStream output = System.out;
        try {
            File f = new File("a.in");
            if (f.exists() && f.canRead()) {
                input = new FileInputStream(f);
                output = new PrintStream("a.out");
            }
        } catch (Throwable e) {
        }
        br = new BufferedReader(new InputStreamReader(input));
        out = new PrintWriter(output);
        solve();
        br.close();
        out.close();
    }

    long largestEven(long x) {
        return x & ~1L;
    }

    long compute(long a, long b) {
        long x = Math.min(a, b);
        long y = Math.max(a, b);
        if (x > 3) {
            return largestEven(x * y);
        }
        long base = y - y % 6;
        int r = (int) (y % 6);
        long h = 0;
        if (x == 1 && r >= 0 && r < H1.length) {
            h = H1[r];
        } else if (x == 2 && r >= 0 && r < H2.length) {
            h = H2[r];
        } else if (x == 3 && r >= 0 && r < H3.length) {
            h = H3[r];
        }
        if (x + y > 9 && x > 1) {
            return largestEven(x * y);
        }
        return base * x + h;
    }

    void solve() {
        long n = nextLong();
        long m = nextLong();
        out.print(compute(n, m));
    }
}
